import{_ as a,a0 as l,w as i,s as r,ao as d,I as s,x as u,a1 as o,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Ubuntu參考手冊14.04 LTS第二版正式發佈 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu參考手冊14.04 LTS第二版正式發佈 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu參考手冊14.04 LTS第二版正式發佈 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu參考手冊14.04 LTS第二版正式發佈 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141230 Second Edition of Ubuntu Manual 14.04 LTS Is Ou","title":"Ubuntu參考手冊14.04 LTS第二版正式發佈","tag":"201412","desc":""},"relativePath":"201412/20141230 Second Edition of Ubuntu Manual 14.04 LTS Is Ou.md","filePath":"[post].md"}'),p={name:"201412/20141230 Second Edition of Ubuntu Manual 14.04 LTS Is Ou.md"};function b(T,t,f,m,S,L){const n=l("Link");return i(),r("div",null,[t[19]||(t[19]=d('<h1 id="ubuntu參考手冊14-04-lts第二版正式發佈" tabindex="-1">Ubuntu參考手冊14.04 LTS第二版正式發佈 <a class="header-anchor" href="#ubuntu參考手冊14-04-lts第二版正式發佈" aria-label="Permalink to “Ubuntu參考手冊14.04 LTS第二版正式發佈”">​</a></h1><blockquote><p>初學者可以在手冊裏獲得很有用的信息</p></blockquote><h3 id="ubuntu參考手冊團隊表示第二版手冊現在已經發布並且可以免費下載" tabindex="-1">Ubuntu參考手冊團隊表示第二版手冊現在已經發布並且可以免費下載 <a class="header-anchor" href="#ubuntu參考手冊團隊表示第二版手冊現在已經發布並且可以免費下載" aria-label="Permalink to “Ubuntu參考手冊團隊表示第二版手冊現在已經發布並且可以免費下載”">​</a></h3><p><img src="http://i1-linux.softpedia-static.com/screenshots/Ubuntu-Manual_1.jpg" alt=""></p><p>Ubuntu手冊按照慣例會對應相應的LTS發行版本，那麼唯一合理的解釋就是，現在發佈的手冊對應於6個月前發佈的Ubuntu 14.04 LTS(Trusty Tahr)。與其他書籍一樣，特別是大型書籍，手冊內容總會出現各種錯誤或者也許已經和現狀不匹配。不過不管怎樣，電子書的修正和更新總要方便一些。</p><p>你也許會覺得奇怪，一個方便上手的免費操作系統竟然會有一個參考手冊，或許一個社區就已經足夠了。但是，總是有一些新用户連基本的操作都不懂，因此，有一本可以指明最基本的東西的手冊拿在手裏總是一個很好不過的事情。</p><h3 id="這是-ubuntu-14-04-lts入門-手冊的第二個版本" tabindex="-1">這是“Ubuntu 14.04 LTS入門”手冊的第二個版本 <a class="header-anchor" href="#這是-ubuntu-14-04-lts入門-手冊的第二個版本" aria-label="Permalink to “這是“Ubuntu 14.04 LTS入門”手冊的第二個版本”">​</a></h3><p>使用Ubuntu操作系統的用户會發現，它和之前用過的其他操作系統有很大的差異，例如Windows和Max OS X。這很正常，並且你也不是任何時候都可以在網上找到一個特定的功能或者組件的相關資源和信息。有一個可以説明Ubuntu 14.04 LTS基本特性的手冊可以提供一些幫助。</p><p>“《Ubuntu 14.04 入門 E2》對於Ubuntu操作系統而言，是一個很全面的初學者指南手冊。它採用的是開源許可協議，你可以自由下載、閲讀、修改以及共享。這個手冊可以幫助你熟悉如何處理日常的工作，例如上網、聽音樂或者掃描文檔等等。尤其值得一提的是，這個文檔淺顯易懂，適合各個層次的用户。”</p>',9)),s("p",null,[t[1]||(t[1]=u("“這個快速入門手冊可以讓你很容易的利用你的計算機做一些事情，而不會陷入技術細節當中。在手冊的幫助下，新用户可以很快的熟悉Unity桌面，”更多信息參考",-1)),o(n,{href:"http://ubuntu-manual.org/"},{default:e(()=>[...t[0]||(t[0]=[u("官方網站",-1)])]),_:1}),t[2]||(t[2]=u("。",-1))]),s("p",null,[t[4]||(t[4]=u("這是該參考手冊的第二版，製作手冊的團隊具有豐富的經驗。就算你已經是一個Ubuntu用户，看一看這個手冊也沒有什麼壞處，因為你總能從其中學到一些東西。你可以在Softpedia",-1)),o(n,{href:"http://linux.softpedia.com/get/Documentation/Ubuntu-Manual-53530.shtml"},{default:e(()=>[...t[3]||(t[3]=[u("下載Ubuntuy參考手冊14.04第二版",-1)])]),_:1}),t[5]||(t[5]=u("。",-1))]),t[20]||(t[20]=s("hr",null,null,-1)),s("p",null,[t[7]||(t[7]=u("via: ",-1)),o(n,{href:"http://news.softpedia.com/news/Second-Edition-of-Ubuntu-Manual-14-04-LTS-Is-Out-468395.shtml"},{default:e(()=>[...t[6]||(t[6]=[u("http://news.softpedia.com/news/Second-Edition-of-Ubuntu-Manual-14-04-LTS-Is-Out-468395.shtml",-1)])]),_:1})]),s("p",null,[t[11]||(t[11]=u("作者：",-1)),o(n,{href:"http://news.softpedia.com/editors/browse/silviu-stahie"},{default:e(()=>[...t[8]||(t[8]=[u("Silviu Stahie",-1)])]),_:1}),t[12]||(t[12]=u(" 譯者：",-1)),o(n,{href:"https://github.com/zhouj-sh"},{default:e(()=>[...t[9]||(t[9]=[u("zhouj-sh",-1)])]),_:1}),t[13]||(t[13]=u(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:e(()=>[...t[10]||(t[10]=[u("wxy",-1)])]),_:1})]),s("p",null,[t[16]||(t[16]=u("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[14]||(t[14]=[u("LCTT",-1)])]),_:1}),t[17]||(t[17]=u(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:e(()=>[...t[15]||(t[15]=[u("Linux中國",-1)])]),_:1}),t[18]||(t[18]=u(" 榮譽推出",-1))])])}const M=a(p,[["render",b]]);export{C as __pageData,M as default};
